// AUTO-GENERATED by scripts/build_deploy_bundle.js — 이 파일을 직접 고치지 마세요.
// 수정하려면 src/theme-blacklist-updater.src.js를 고친 뒤 `node scripts/build_deploy_bundle.js`를 다시 실행하세요.
// 공통 포맷/유틸 헬퍼 — 여러 노드 소스에 복붙되어 있던 것을 통합.
//
// 주의(swing-scanner.src.js는 이 pct()를 쓰지 않는다): swing_scanner_code.js의 기존 pct()는
// 부호를 붙이지 않는 버전이었다(호출부 템플릿에서 '(+' / '(-'를 직접 문자열로 적어왔기
// 때문). 여기 pct()는 weekly_reporter/Daily_Position_Monitor가 쓰던, 값의 부호에 따라
// +/-를 스스로 붙이는 버전이다. 동작을 하나로 강제 통합하면 swing-scanner 쪽 메시지에
// 부호가 두 번 붙는 회귀가 생기므로, swing-scanner.src.js는 의도적으로 자기 파일 안에
// 부호 없는 pct()를 그대로 로컬로 유지한다.
function pct(r) {
  return (r >= 0 ? '+' : '') + (Number(r) * 100).toFixed(1) + '%';
}

// to0(): Daily_Position_Monitor의 기존 버전은 Number() 방어가 없었다(비정상 입력 시 'NaN'
// 문자열 노출). swing_scanner_code.js의 방어적인 버전(Number(n) || 0)을 정본으로 채택.
function to0(n) {
  return Math.round(Number(n) || 0).toLocaleString('ko-KR');
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// Telegram sendMessage 래퍼 — 여러 노드 소스에 복붙된 POST 요청을 통합.
// send()는 에러를 스스로 삼키지 않는다(순수 http() 호출 그대로) — 호출부마다
// try/catch 유무가 달랐던 기존 동작을 그대로 보존하기 위함.
function createTelegram(http, botToken, chatId) {
  const send = (text) => http({
    method: 'POST',
    url: 'https://api.telegram.org/bot' + botToken + '/sendMessage',
    json: true,
    body: { chat_id: chatId, text },
  });
  return { send };
}


const store = this.getWorkflowStaticData('global');
if (!store.blacklist) store.blacklist = {};

const http = async (o) =>
  await this.helpers.httpRequest(
    Object.assign(
      {
        timeout: 30000,
      },
      o
    )
  );

// Naver Finance가 Next.js 프론트로 개편되며 구 HTML(theme.naver/sise_group_detail.naver)
// 스크래핑이 영구 실패하게 됨 → 모바일 JSON API(m.stock.naver.com)로 교체
async function fetchJson(url) {
  return await http({
    method: 'GET',
    url,
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
      Referer: 'https://m.stock.naver.com/',
    },
    json: true,
  });
}

async function fetchJsonRetry(url, tries = 2) {
  let lastErr;
  for (let i = 0; i < tries; i++) {
    try {
      return await fetchJson(url);
    } catch (e) {
      lastErr = e;
      await sleep(300 + i * 500);
    }
  }
  throw lastErr;
}

// 정치 테마 키워드 — 여기에 원하는 키워드를 추가/제거하세요
const POLITICAL_KEYWORDS = [
  '대선', '대통령', '총선', '선거', '정치', '국회', '의원',
  '여당', '야당', '공천', '후보', '당대표', '대권', '집권',
  '국정감사', '탄핵', '윤석열', '이재명', '한동훈',
];

function isPoliticalTheme(name) {
  return POLITICAL_KEYWORDS.some((kw) => name.includes(kw));
}

async function mapLimit(list, limit, worker) {
  const results = [];
  const errors = [];
  let idx = 0;

  const runners = new Array(Math.min(limit, list.length)).fill(0).map(async () => {
    while (idx < list.length) {
      const i = idx++;
      try {
        results[i] = await worker(list[i], i);
      } catch (e) {
        errors.push({ i, item: list[i], message: e?.message || String(e) });
        results[i] = null;
      }
    }
  });

  await Promise.all(runners);
  return { results, errors };
}

// ====== 튜닝 포인트(차단/느림이면 여기만 조절) ======
const MAX_LIST_PAGES = 20;     // 테마 목록 페이지 최대 탐색
const CONCURRENCY = 6;         // 테마 상세 동시 요청 수 (차단되면 3으로 낮추세요)
const DETAIL_SLEEP_MS = 120;   // 상세 요청 사이 아주 짧은 텀(차단 완화)
const LIST_SLEEP_MS = 120;     // 목록 페이지 요청 텀
// =====================================================

const startTs = Date.now();

// 1) 테마 목록 수집 (테마번호 + 테마명)
const first = await fetchJsonRetry(`https://m.stock.naver.com/api/stocks/theme?page=1&pageSize=100`, 2);
const firstGroups = (first && first.groups) || [];

if (firstGroups.length === 0) {
  return [
    {
      json: {
        ok: false,
        reason: 'No theme entries found on list page',
      },
    },
  ];
}

let allEntries = firstGroups.map((g) => ({ no: String(g.no), name: String(g.name || '').trim() }));
let maxPage = Math.min(Math.ceil((first.totalCount || allEntries.length) / 100), MAX_LIST_PAGES);
let stoppedEarlyAtPage = null;

for (let p = 2; p <= maxPage; p++) {
  await sleep(LIST_SLEEP_MS);
  const r = await fetchJsonRetry(`https://m.stock.naver.com/api/stocks/theme?page=${p}&pageSize=100`, 2);
  const groups = (r && r.groups) || [];
  if (groups.length === 0) {
    stoppedEarlyAtPage = p;
    break;
  }
  for (const g of groups) allEntries.push({ no: String(g.no), name: String(g.name || '').trim() });
}

// 2) 정치 테마만 필터링
const politicalEntries = allEntries.filter((e) => isPoliticalTheme(e.name));
const themeNos = politicalEntries.map((e) => e.no);

// 3) 정치 테마 상세에서 종목코드 수집(동시처리)
const codeSet = new Set();
const detailErrors = [];

const { errors } = await mapLimit(themeNos, CONCURRENCY, async (no) => {
  await sleep(DETAIL_SLEEP_MS);
  let codesCount = 0;
  for (let p = 1; ; p++) {
    const r = await fetchJsonRetry(`https://m.stock.naver.com/api/stocks/theme/${no}?page=${p}&pageSize=100`, 2);
    const stocks = (r && r.stocks) || [];
    for (const s of stocks) {
      const c = String(s.itemCode || '');
      if (c) { codeSet.add(c); codesCount++; }
    }
    if (!r || !r.totalCount || stocks.length === 0 || p * 100 >= r.totalCount) break;
  }
  return { no, codesCount };
});

if (errors.length) detailErrors.push(...errors);

// 4) 저장 + 텔레그램 알림 + 리턴 (라이브 노드의 FIX C-4 / FIX W-6 패턴 그대로 유지)
const themeCodes = [...codeSet].sort();
const prevThemeCodes = Array.isArray(store.blacklist.themeCodes) ? store.blacklist.themeCodes : [];
const BOT_T = SECRETS.BOT;
const CHAT_T = SECRETS.CHAT;
const NL_T = String.fromCharCode(10);
const telegram = createTelegram(http, BOT_T, CHAT_T);

// FIX C-4 (정치 필터 대응 수정): "정치 테마 자체가 0건"과 "상세 조회 실패로 0건"을 구분한다.
// - politicalEntries.length === 0: 목록 스크래핑은 성공(allEntries>0)했고 정치 테마가 정상적으로 없는 것 → 정상 결과로 반영(캐시 비움)
// - politicalEntries.length > 0인데 themeCodes가 0건: 상세 페이지 조회가 전부 실패한 네트워크 문제 → 기존처럼 캐시 유지
if (themeCodes.length === 0 && politicalEntries.length > 0 && prevThemeCodes.length > 0) {
  try {
    await telegram.send(
      '⚠️ [테마 블랙리스트] 정치 테마 ' + politicalEntries.length + '개 매칭됐으나 상세 조회 실패 — 기존 캐시 유지' + NL_T + '기존: ' + prevThemeCodes.length + '개'
    );
  } catch (e) {}
  return [{ json: { ok: true, keptCache: true, themeCodesCount: prevThemeCodes.length } }];
}

store.blacklist.themeCodes = themeCodes;
store.blacklist.themeUpdatedAt = new Date().toISOString();
store.blacklist.themeNosCount = themeNos.length;
store.blacklist.themeSource = 'naver:m.stock.api:political_only';
store.blacklist.themeFetchStats = {
  stoppedEarlyAtPage,
  maxPageTried: maxPage,
  concurrency: CONCURRENCY,
  detailErrors: detailErrors.length,
  ms: Date.now() - startTs,
  totalThemesFound: allEntries.length,
  politicalThemesMatched: politicalEntries.length,
  politicalThemeNames: politicalEntries.map((e) => e.name),
};

// FIX W-6: 성공 알림 (전체 테마 수 대비 정치 테마 매칭 수 반영)
try {
  await telegram.send(
    '✅ [테마 블랙리스트 갱신 성공]' + NL_T +
    '총 ' + themeCodes.length + '개 종목 / 정치 테마 ' + themeNos.length + '개 (전체 ' + allEntries.length + '개 중)' + NL_T +
    '갱신: ' + store.blacklist.themeUpdatedAt
  );
} catch (e) {}

return [
  {
    json: {
      ok: true,
      done: true,
      totalThemesFound: allEntries.length,
      politicalThemesMatched: politicalEntries.length,
      politicalThemeNames: politicalEntries.map((e) => e.name),
      themeNosCount: themeNos.length,
      themeCodesCount: themeCodes.length,
      themeUpdatedAt: store.blacklist.themeUpdatedAt,
      stats: store.blacklist.themeFetchStats,
      sampleCodes: themeCodes.slice(0, 20),
      detailErrors: detailErrors.slice(0, 10),
    },
  },
];
